while IFS= read -r f; do
  jq -rc '
    (reduce (inputs? // empty) as $x ({}; .)) ' /dev/null 2>/dev/null
done < "$L" >/dev/null
# Build id->command map and denied-id set per file, then join
python3 - "$L" <<'PY'
import json,sys,collections
L=open(sys.argv[1]).read().split()
idmap={}
denied=collections.Counter()
deniedkind=collections.defaultdict(collections.Counter)
for path in L:
    local_id={}
    try:
        lines=open(path,encoding='utf-8',errors='ignore').read().splitlines()
    except: continue
    for ln in lines:
        ln=ln.strip()
        if not ln: continue
        try: o=json.loads(ln)
        except: continue
        if o.get('type')=='assistant':
            for c in (o.get('message',{}).get('content') or []):
                if isinstance(c,dict) and c.get('type')=='tool_use':
                    local_id[c.get('id')]={'name':c.get('name'),'input':c.get('input') or {}}
        if o.get('type')=='user':
            kind=o.get('toolDenialKind')
            if not kind: continue
            for c in (o.get('message',{}).get('content') or []):
                if isinstance(c,dict) and c.get('type')=='tool_result':
                    tid=c.get('tool_use_id')
                    tu=local_id.get(tid)
                    if not tu: 
                        denied[('<unresolved>','')]+=1; deniedkind[('<unresolved>','')][kind]+=1; continue
                    name=tu['name']; inp=tu['input']
                    if name=='Bash':
                        cmd=(inp.get('command') or '').strip()
                        parts=cmd.split()
                        key='Bash: '+' '.join(parts[:2]) if parts else 'Bash: <empty>'
                    elif name.startswith('mcp__'):
                        key='MCP: '+name
                    else:
                        key=name
                    denied[(key,'')]+=1
                    deniedkind[(key,'')][kind]+=1
for (k,_),n in denied.most_common():
    kinds=dict(deniedkind[(k,'')])
    print(f"{n:3d}  {k}   kinds={kinds}")
PY

